namespace GeetaStudio.Api;

public static class TalkPage
{
    public const string Html = """
<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>Talk with Dadaji</title>
<style>body{font:18px system-ui;max-width:780px;margin:2rem auto;padding:1rem;line-height:1.6}label{display:block}input,select,textarea,button{font:inherit;padding:.5rem;margin:.3rem 0;max-width:100%;box-sizing:border-box}textarea{width:100%}button{cursor:pointer}#answer{white-space:pre-wrap}aside{background:#f4f1e7;padding:1rem}a{color:#245c69}</style>
<main><a href="/account">Account and credits</a><h1>Talk with Dadaji</h1><aside>Dadaji is a fictional AI character. This private English learning sample quotes supported passages and invites reflection. It is not divine authority, current news or professional/crisis care. Human and live release qualification is pending.</aside>
<label>Workspace <input id="tenant" placeholder="Workspace identifier"></label><button id="load">Load my profiles</button><label>My profile <select id="profile"></select></label><label>Reviewed learning capability <select id="policy"></select></label><label><input type="checkbox" id="remember">Remember this session (adults with current account consent only; at most 24 hours)</label><button id="open">Start conversation</button><p id="limits"></p>
<label for="question">Your question</label><textarea id="question" maxlength="2000" rows="3" placeholder="Where did the opposing armies gather?"></textarea><button id="ask">Ask and show answer</button><button id="cancel">Cancel session</button><button id="forget">Delete conversation memory</button><button id="history">Show retained conversation</button><p id="status" role="status" aria-live="polite"></p><div id="answer"></div><h2>Sources and suggested reading</h2><div id="sources"></div><p id="cost"></p><p id="reflection"></p><label>Report a problem <select id="category"><option>Citation</option><option>Unsafe</option><option>Incorrect</option><option>Privacy</option><option>Other</option></select></label><button id="report">Send private problem report</button><button id="reconcile">Check unresolved usage</button></main>
<script>
const $=id=>document.getElementById(id);let session=null,last=null,policies=[],pendingTurn=null;function base(){return '/api/v1/customer/tenants/'+encodeURIComponent($('tenant').value.trim())}
async function api(path,body){const r=await fetch(base()+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','X-ContentOS-Staff':'1'}:{},body:body?JSON.stringify(body):undefined});if(!r.ok){let e=await r.json();throw Error(e.error||'Request rejected')}return r.status===204?null:await r.text().then(x=>x?JSON.parse(x):null)}async function work(f){try{$('status').textContent='Working…';await f();$('status').textContent='Done.'}catch(e){$('status').textContent=e.message}}
function options(id,rows,label){$(id).replaceChildren();for(const x of rows){const o=document.createElement('option');o.value=x.id;o.textContent=label(x);$(id).append(o)}}
function show(x){last=x;$('answer').textContent=x.answer||'Content was not retained. Accounting and sources remain available.';$('cost').textContent='Credits consumed: '+x.credits+'; provider cost: '+x.providerCost+' '+(x.currency||'')+'; outcome: '+x.outcome;$('reflection').textContent=x.reflection;$('sources').replaceChildren();for(const s of x.sources){const p=document.createElement('p');p.textContent='Chapter '+s.chapter+', verse '+s.verse+' · '+s.label+' · '+s.exactText+' · '+s.citation.requiredAttribution;try{const u=new URL(s.locator);if(u.protocol==='https:'||u.protocol==='http:'){const a=document.createElement('a');a.href=u.href;a.textContent=' Open source';a.target='_blank';a.rel='noopener noreferrer';p.append(a)}}catch{}const detail=document.createElement('a');detail.href=base()+'/talk/sessions/'+session+'/turns/'+x.id+'/sources/'+s.corpusTextId;detail.textContent=' Open cited passage';p.append(detail);$('sources').append(p)}}
$('load').onclick=()=>work(async()=>{options('profile',await api('/profiles'),x=>x.alias+' · '+x.ageBand+' · '+x.locale);policies=await api('/talk/policies');options('policy',policies,x=>x.settings.key+' · '+x.settings.ageBand+' · private fixture')});$('open').onclick=()=>work(async()=>{session=await api('/talk/sessions',{operationId:crypto.randomUUID(),profileId:$('profile').value,policyId:$('policy').value,remember:$('remember').checked});const x=await api('/talk/sessions/'+session);$('limits').textContent=x.disclosure+' Expires '+x.expiresUtc+'; maximum '+x.maxTurns+' turns; up to '+x.creditsPerTurn+' credits per supported turn. Memory: '+(x.remember?'this session only':'off; questions/answers are not stored')});
$('ask').onclick=()=>work(async()=>{if(!session)throw Error('Start a session first');$('ask').disabled=true;try{if(!pendingTurn||pendingTurn.question!==$('question').value)pendingTurn={operationId:crypto.randomUUID(),question:$('question').value};show(await api('/talk/sessions/'+session+'/turns',pendingTurn));pendingTurn=null}finally{$('ask').disabled=false}});$('cancel').onclick=()=>work(()=>api('/talk/sessions/'+session+'/cancel',{}));$('forget').onclick=()=>work(async()=>{await api('/talk/sessions/'+session+'/forget',{});$('answer').textContent='Conversation memory deleted.';$('question').value=''});$('history').onclick=()=>work(async()=>{const x=await api('/talk/sessions/'+session);$('answer').textContent=x.turns.map(t=>(t.question||'[not retained]')+'\n'+(t.answer||'[not retained]')).join('\n\n')});$('report').onclick=()=>work(()=>api('/talk/sessions/'+session+'/turns/'+last.id+'/report',{operationId:crypto.randomUUID(),category:$('category').value}));$('reconcile').onclick=()=>work(async()=>show(await api('/talk/sessions/'+session+'/turns/'+last.id+'/reconcile',{})));
</script></html>
""";
}



